INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1044001-econ101', 'stk-faisal-fin', 'ECON 101', 'info', '{"desc": "الكورس يتكلم عن مبادئ الأقتصاد للأفراد والمؤسسات\n\nفي البداية بيشرح لك اهمية التفكير الأقتصادي والحلول يلي قدمها للناس مع بعض النظريات العامة\nواهمها (الطلب والعرض)\n\nبعدها بيشرح لك كيف الشخص او رب الأسرة يستفيد ويوزع من دخله في الأستهلاك والأستثمار بشكل عملي وعقلاني وبعدها بيشرح لك إيش لازم تسوي الشركات والمؤسسات عشان تحقق اعلى مكاسب عن طريق اختيار سعر مناسب للمنتج وايضا محاولة تقليل تكلفة الانتاج و طبعا لان المادة مبادئ فراح يعرض لك عدة انظمة اقتصادية لكل نظام شروط وقوانين بعضها تخدم الافراد بشكل كبير وبعضها تخدم اصحاب الشركات ورؤس الاموال وبعضها يكون محايد\n\nضروري تفهم الرسمات يلي تدرسها لانها بأختصار تلخص لك كلام كثير وتسهل عليك فهم المادة مستقبلا بدل ماتحفظ القانون ككلام خلي الرسمة في بالك\n\nالكتاب حق المادة ممتاز من ناحية سهولة فهم الأفكار ويعرض لك امثلة تساعدك على فهم الفكرة من كل زواياها فحاول تعتمد عليه مبديئا واستخدم الهايلايتر للتحديد على السطور المهمة\n\nالتي بي ضروري تراجعه قبل الكويزات والمياجر لسببين … اول شيء لان اسئلته تقيس فهمك للنظريات من جميع زواياها وهذا مهم جدا جدا لا تحفظ النظرية افهمها زيييين وثاني سبب بتشوفه وانت تحل الأختبار 👍", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/econ-101-principles-of-economics-i-micro/121027/4", "user": "Faisal-FIN", "ts": 1337895630000, "tid": 121027, "pn": 4}}', 1337895630000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1114691-econ101', 'stk-user4583', 'ECON 101', 'info', '{"desc": "الى الأخ سونه ،\n\nالله يجزاك الجنه و يسهل عليك امورك ولا يجعلك ترى مكروه،\n\nالله يجعلك قادر ع تحقيق كل ماتتمناه وتطمح له ، ويرزقك ببنت الحلال اللي تسعدك وتجعلك من اسعد الناس ع وجه الأرض ،،\n\nالله يرزقك سعاده في الدنيا و وسع في القبر ، ونعيمٌ في الاخره،،،\n\nهاااه يا رجل خوووذلك بوووسه ، امووواااااح 🙂\nههههههههههههههه\n\nشكرا لك.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/econ-101-principles-of-economics-i-micro/121027/6", "user": "user4583", "ts": 1352483485000, "tid": 121027, "pn": 6}}', 1352483485000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1316178-econ101', 'stk-user8581', 'ECON 101', 'info', '{"desc": "جودة المقرر بشكل عام\nجيد … بشكل عام يعطيك فكرة مبسطة عن الاقتصاد وبعض النظريات مثل فكرة العرض والطلب والتبادل و المصطلحات الاقتصادية .\nالمواضيع التي يغطيها المقرر\nالكورس فيه 15 شابتر وتتركز في اول خمس شباتر على opportunity cost و الـ demand و الـ supply والعلاقة بينهم والأمور الي تأثر في هذي العلاقة بالنسبة للمستهلك والشباتر الي بعدها تكون متعلقة بنفس الفكرة لكن مع الشركات وفي المدى القصير والبعيد .\nمن شابتر 10 - 15 تتركز على imperfectly competitive markets\nوهذي سلايدات للكورس … الي اشوف مذاكرتها وفهم الرسمات + حفظ المصطلحات افضل طريقة شعان تحصل على قريد طيب …وانا ذاكرت منها + الكتاب والحمدلله طلعت بـ a\nhttp://faculty.kfupm.edu.sa/finec/murahman/teaching/Econ%20101/Power%20Point%20Slides/\n\nالكتاب المستخدم للمقرر\nنوعا ما جيد لكن في بعض الأمور سهلة وهو معقدها + فيه كلام كثير , الي عنده وقت فاضي وانجليزيته ممتازة انصحه يقرأ الكتاب لأنه يحتوي على امثلة تشرح النظريات والمفاهيم الي في الكورس .\n\n…\nالكورس نظام الدرجات والاختبارات اشوي ملخبط ويكون على حسب دكتورك\nالعبندي : احيانا افرج واحيانا استنادرد وميجر خاص بطلابه.\nإبراهيم القحطاني + الغامدي : ستنادرد والمياجر تكون مشتركة بينهم .\nأسامة عثمان : افرج وميجر خاص بطلابه\n+\nالمياجر والفاينل مب comprehensive هذا احسن شي في هذي المادة .\nوصلت الى نتيجة في دكاترة الـ ECON 101\nشرح ممتاز+بونصات+ كويز كل كلاس+مياجر MCQ بين السهل والمتوسط = إبراهيم القحطاني\nشرح لك عليه+ يدف في الدرجات + مياجر ريتين + MCQ = حسن العبندي\nشرح ممتاز+ مياجر صعبة + الكورس افرج = أسامة عثمان", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/econ-101-principles-of-economics-i-micro/121027/9", "user": "user8581", "ts": 1389022084000, "tid": 121027, "pn": 9}}', 1389022084000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1518442-econ101', 'stk-nawafmkz', 'ECON 101', 'info', '{"desc": "Microeconomics - econ101\nكورس مهم جدا ومفيد بشكل كبير لكن للأسف يدرس في الجامعة بأسوء طريقة ممكنة، طريقة التدريس ونوعية الدكاترة مخليه الكورس من أسوء الكورسات اللي تمر على الواحد لا من ناحية شرح ولا تعامل واختبارات.\nإذا كان د. أسامة هو الكوردينتر فنوتته هي المصدر الاساسي للمذاكرة - النوتة مختصرة جدا جدا جدا وتحتاج تسجل مع الدكتور وهو يشرح او من مذاكرتك من اليوتيوب.\nالاختبارات غالبا صعبة. الكورس يحتاج متابعه أول بأول خصوصا انه مترابط من اول الشباتر الى اخرها.\n#مرفق توزيع الدرجات 191\n\nCourse Semester Average: 54.1\n90 < A+\n80 ≤ A ≤ 90\n75 ≤ B+ < 80\n70 ≤ B < 75\n62 ≤ C+ < 70\n53 ≤ C < 62\n48 ≤ D+ < 53\n43 ≤ D < 48\nF < 43", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/econ-101-principles-of-economics-i-micro/121027/14", "user": "NawafMKZ", "ts": 1577657871000, "tid": 121027, "pn": 14}}', 1577657871000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1526119-econ101', 'stk-practice', 'ECON 101', 'info', '{"desc": "المادة ممتازة ومواضيعها حلوة ومفيدة جداً ، لكن المشكلة في الدكاترة اللي يدرسوها حالياً وما انصحك تاخذها صراحة\n\nMgt210 مع ماكسويل ما راح تتعبك ان شاء الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/econ-101-principles-of-economics-i-micro/121027/17", "user": "Practice", "ts": 1602280325000, "tid": 121027, "pn": 17}}', 1602280325000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1527790-econ101', 'stk-user12012', 'ECON 101', 'info', '{"desc": ".\n.\nللأسف الكورس في الجامعة كما قيل : “كورس مهم جدا ومفيد بشكل كبير لكن للأسف يدرس في الجامعة بأسوء طريقة ممكنة، طريقة التدريس ونوعية الدكاترة مخليه الكورس من أسوء الكورسات اللي تمر على الواحد لا من ناحية شرح ولا تعامل واختبارات”، هذا الجانب المظلم من المادة. الجانب المشرق منها أن المادة ممتعة ومخدومة بشكل كبير من ناحية مصادر المذاكرة بعيدًا عن تعقيدات المادة داخل أسوار الجامعة. سأسردها هنا :\n\n١) سلسلة محاضرات لـ Prof. Jonathan Gruber في جامعة MIT، أمتع وأفضل من رأيت يشرح المادة، تحتاج أول ١٤ محاضرة فقط منها لتغطية المقرر عندنا. السلبية الوحيدة انك قد تواجه عدم توافق بين المقرر عندنا والمحاضرات لكن في المجمل ما راح يأثر.\n\nأنصح بها وبشدة خصوصًا للي حاب المادة\n\nhttps://youtube.com/playlist?list=PLUl4u3cNGP62oJSoqb4Rf-vZMGUBe59G-\n\n٢) Khan Academy عندهم كورس مايكرو ممتاز ايضًا، فكرته انه يعرض لك مقاطع قصيرة (٥-١٠ دقايق) كل مقطع لفكرة او جزئية من الدرس وفيه اختبارات عليها وتقدر تعرف اداءك ومستواك في كل درس، ميزاته :\n\n*مجاني بشكل كامل *متوافق بشكل كبير مع المقرر عندنا. *يعطيك اسئلة وكويزات على كل درس. *مختصر وواضح ومقسم الى مقاطع قصيرة.\n\nأنصح به.\nMicroeconomics\n\n٣) مقاطع Jacob Clifford , مجموعة مقاطع قصيرة لكل درس او لجزئية كبيرة منه، ميزتها : أنها مختصرة جدًا ويركز على الجزئيات المهمة.\nيعيبها انها مختصرة جدًا (كونها Microeconomics AP “لطلاب الثانوي”) لدرجة انها ما تغطي المقرر اضافة إلى انها غير مرتبة وليست مجانية بشكل كامل.\n\nانصح بها للطالب “الداج” في المادة أو اللي مب مهتم لها ولغيرهم كمصدر ثانوي للمذاكرة\n*مقاطع السمري وحل الاسئلة جيدة وانصح بها قبل الاختبارات\n\nMicroeconomics Videos\n\n٤) الكتاب المقرر في الجامعة Economics by Richard Lipsey 13th , الكتاب شكله مرعب وكئيب لكنه جيد ويعطيك تصور افضل للمادة.\nانصح بقراءته، قد تواجه صعوبة من ناحية اللغة؛ استعن بالمترجم.\n\n٥) هذا Textbook آخر بعنوان Principles of Economics, N. Gregory Mankiw قرأت أول تشابتر منه فقط وكان جميل وممتع، يستخدم أمثلة واقعية ومعاصرة كون الكتاب حديث، يستخدم صور وألوان ورسوم بشكل كبير مقارنة بالكتاب المقرر الكئيب قليلًا 🙂 . تمنيت لو كان مقرر عندنا.\n\nتجد الكتاب هنا : KFUPM Resources\n\n-» هذي بعض المصادر التي توصلت لها واراها جيدة، قد تفيدك من ناحية فهم المادة، لستَ ملزمًا بها جميعًا اختر المناسب لك.\n\nههنا توزيع القريدات - T201 (عن بعد) :\n\nA+ >=89\nA >=84\nB+ >=80\nB >=76\nC+ >=71\nC >=69\nD+ >=66\nD >=60\nF <60\n\n.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/econ-101-principles-of-economics-i-micro/121027/18", "user": "user12012", "ts": 1610306507000, "tid": 121027, "pn": 18}}', 1610306507000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1533504-econ101', 'stk-abo_ras', 'ECON 101', 'info', '{"desc": "ECON 101 -TERM 211\n\nالماده متوسطة الى صعبة واهم شي انك تفهم كل ال Figures الموجوده في الكتاب وبتمشي امورك\n\nاول 4 تشابتر كانت سهله وواضحة بعدها الوضع يصير اصعب فلا تنخدع بالميجر الاول\n\nاخذت الماده مع حسين الشماسي والدكتور كان عسل وواجباته وكويزاته كان يجي منها كثير في المياجر والفاينل فركز عليها مره\nوهذا توزيع القريدات ترم 211\n\n92-100 +A\n\n86-91 A\n\n80-85 +B\n\n75-80 B\n\n69-74 +C\n\n62-68 C\n\n54-61 +D\n\n50-53 D\n\n0-49 F", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/econ-101-principles-of-economics-i-micro/121027/19", "user": "abo_ras", "ts": 1642437605000, "tid": 121027, "pn": 19}}', 1642437605000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1535193-econ101', 'stk-don_quixote_875', 'ECON 101', 'info', '{"desc": "Economics 101 - Term 213\n\nبعيدا عن الترهيب والتخويف اللي تسمعونه من طلاب الكلية وان المادة تعتبر physics الادارة، المادة تعتبر مقدور عليها وتقدر تطلع بدرجة حلوة\n\nالحمدلله طلعت فيها ب A+ رغم اني كنت عند دكتور مب كويس بالصيف\n\nافهم الرسمات زين لانها اهم شي، اذا ما تفهم الرسمات ف انت ما تفهم Economics\n\nطبعاً المادة هذي 14 تشابتر يعني تقريباً كل اسبوع تخلص تشابتر والنهائي comprehensive يعني المنهج كامل لكن ال chapters تعتبر خفيفة بالنسبة لاول خمسة تشابتر اذا تذاكرهم اول باول لكن لا تستهين فيها، حاول تخلص كل اسبوع chapter او اثنين وقبل كل ميجر والنهائي حل الاختبارات الكاملة اللي موجودة على my lab (فيه اختبارين على كل chapter وتقدر تحل quiz me كمراجعة وتشوف الاشياء اللي ناسيها وتحاول تراجعها\n\nالمصادر:\n\n1- تقرا الكتاب\n2- تحل ال study plan\n3- تحل ال Dynamic Study Modules (لا تغني عن عن اول ثنتين لان هم الاساس ولكنها مفيدة للمراجعة و التاكد من المعلومات وتعتبر خفيفة وسريعة)\n\nال dynamic study modules هو تطبيق مسوينه شركة Pearson وفيه اسئلة تحل عليه لكنها اسهل من حقت ال study plan\n\nاقرا الكتاب لان السلايدات مافيها كل المعلومات وما اشوفها تعطيك المعلومة كاملة مثل الكتاب (الكتاب جداً ممتاز ورهيب)\n\nوبعدها حل\nال study plan ال study plan ال study plan\n\nعليك فيه، حله كامل وباذن الله بتطلع بقريد حلو حتى لو دكتورك سيء لان المادة تعتمد على المذاكرة الذاتية او ال self-study\n\nال study plan ياخذ وقت شوي بس اذا حليته كامل باذن الله بتطلع بقريد عالي، لان حل الاسئلة في ذي المادة بالغ الاهمية\n\nجودة المقرر بشكل عام\n\nالمقرر جودته ممتازة جداً\n\nالمواضيع التي يغطيها المقرر\n\nالمقرر يغطي الاقتصاد الجزئي او ال Microeconomics خلال 14 chapters وينقسم الى 6 parts منهم اثنين ما راح تاخذونهم ( يعني بتاخذون اربعة)\n\nانصحك تقرا الصفحات من 5 الى 15 عشان تعرف زين وش بتدرس قبل وقت الدراسة وترى ال mathematical notes مهمة ولازم تخلصها لانها موجودة في ال syllabus\n\nطبعاً ترى اخر اربع فصول هي يمكن اثقل شي ف حاول تسد فيها وافهم فصل 10 و 11 خصوصاً رسمات ال total cost وال average cost مع الجدول حقهم لانك لازم ترسمهم واخر اربع فصول تعتمد عليهم بشكل كبير\n\nPart 1:\nهو مقدمة للاقتصاد ويشمل اول فصلين\n\nالفصل الاول\nيشرح لك وش هو الاقتصاد وليش ندرسه ويتكلم عن الندرة وكيف انك لازم تتنازل عن شي عشان تحصل على شيء اخر ومفهوم ال opportunity cost وراح يتطرق في البداية لل معضلة الاقتصادية اللي هي ان عندك رغبات لا محدودة وموارد محدودة\n\nالفصل الثاني\n\nيتعمق ويوضح لك المفاهيم في ال chapter الاول باستخدام رسمات ويفرق لك بين ال production efficiency وال allocative efficiency ويوريك ان التخصصية ترفع مدخول الكل وتفيد الجميع بعدها يتطرق للنمو الاقتصادي\n\nPart 2:\nكيفية عمل الاسواق\n\nالفصل الثالث\n\nاعتبره احد اهم الفصول ان لم يكن اهمها واللي تتمحور حوليه المادة بشكل عام واللي هو demand and supply لان بعدين بيوريك اياها من اكثر من جهة ومن اكثر من زاوية خلال المادة طبعاً لازم تفرق بين ال Demand وال quantity demand\n\nوبعد لازم تفرق بين ال supply وال quantity supplied\n\nوالفصل يذكر الاشياء اللي تسبب تحرك هذه الرسمات سواء بالزيادة او النقص\n\nالفصل الرابع:\nElasticity of supply and demand\nاو مرونة العرض والطلب\n\nيتكلم فيه عن متى يكون العرض والطلب مرنين ومتى يكونون غير مرنين ولازم باستخدام القانون (بسيط وسهل بس حاول تفرق بين القوانين)\nطبعاً هذا ال chapter يعتمد ال demand and supply curve\n\nالفصل الخامس:\nيتكلم عن الكفاءة والعدل ويذكر بعض النظريات الاقتصادية مثل ال utilitarianism وهي اكبر سعادة لاكبر عدد و اللي تبدو كويسة ومفيدة وعادلة للوهلة الاولى لكن بالواقع تكون العكس تماما\n\nالفصل السادس\n\nيتكلم عن قرارات الحكومة (مثل فرض الضرائب او فرض حد ادنى للرواتب او وضع حد اعلى للكمية او وضع حد ادنى للاجار) او في السوق وكيف انها تاثر سلباً احيانا بدال ما تكون ايجابية وقد تخلق بطالة او سوق سوداء او غير ذلك\n\nالفصل السابع كان محذوف في ترمنا\n\nPart 3:\nاختيارات الاشخاص\n\nالفصل الثامن:\nيتكلم عن ال utility and demand\n\nوفيه يتكلم عن الفائدة وانها تقل كل ما زادت وفرة الشيء، المتوفر وسهل الوصول قيمته اقل تكون وبعدها يذكر بعض المجالات الفرعية في علم الاقتصاد\n\nالفصل التاسع:\n\nالاحتمالات، التفضيلات، والاختيارات\n\nيتكلم عن الفائدة او ال utility اللي ذكرت بالفصل الثامن ويربطها مع ال indifference curve واللي تفرق لك بين المرغوب والغير مرغوب ويتكلم عن الاحتمالات اللي ممكن تاخذها لكل خيار وبعدها يتكلم عن افضل خيار لك ( واللي هو تقاطع ال indifference curve مع ال budget line)\n\nPart 4:\n\nالشركات والاسواق\n\nالفصل العاشر\n\nوفيه يتكلم عن الكفاءة التقنية والكفاءة الاقتصادية والهدف الاساسي من اي شركة (اللي هو الحصول على اقصى ربح) ويتكلم عن الفرق بين ال accounting profit وال economic profit\n\nبالمحاسبة فقط يحطون الارباح المالية والخسائر المالية سواء ملموسة او غير ملموسة لكن بالاقصاد لازم تحسب الفرص اللي بتخسرها اذا اخذ خيار بدال خيار ثاني وهذا يرجعنا لمفهوم ال opportunity cost وال tradoffs او التنازلات\n\nوبعدها يتكلم عن مشكلة المالك والموظف وكيف ان الموظف ما يهتم لارباح شركة المالك الا اذا كان فلوسه وربحه مربوط بربه المالك\n\nالفصل الحادي عشر\n\nهذا الفصل هو لبنة الاساس لكل الفصول الجاية\n\nافهم الرسمات حقت ال total cost وال marginal cost و ال average cost\n\nوبرضو افهم ال total product و ال marginal product وال average product\n\nالفصل الثاني عشر\n\nيتكلم عن السوق اللي فيه التنافس مثالي وكيف ان الشركات تعتبر فيه price takers بمعنى انهم يفرض عليهم انهم ياخذون سعر السوق عشان ما يفلسون\n\nالفصل الثالث عشر\n\nالاحتكار وكيف ينشا سواء بشراء الشخص لشركة محتكرة السوق او بانشاء شركة تحتكر السوق عن طريق دعم السياسات واخذ الرخص منهم حين وصولهم لمناصب والفصل هذا يوريك كيف ان الاحتكار سيء جداً ومصر اقتصادياً\n\nالفصل الرابع عشر\n\nالمنافسة الاحتكارية\n\nوهذا الفصل يعتبر قريب للفصل الثاني عشر من ناحية السلوك ف هو يسلك سلوك ال perfectly competitive market لكن يرسم مثل ال monopoly\n\nالفصل الخامس عشر\n\nعن ال oligopoly واللي يعتبر اقرب لل monopoly\n\nوهو اجمل فصل بالنسبة لي لانه يتطرق لواحد من اهم مجالات الاقتصاد والرياضيات وهو ال game theory وبعدها يذكر لك الالعاب المتوالية والمعادة واخر شي يذكر لك ال antitrust laws واللي تساعد في منع ال oligopolies من تطورها الى ان تكون monopolies\n\nُالكتاب المستخدم للمقرر\nEconomics by Michael Parkin 13th international\nedition\n\nالأسئلة والأمثلة المستخدمة في المقرر\n\nطبعاً الكتاب يعطيك امثلة واقعية ومكتوب بشكل جداً سلس ومرتب مما يسهل الفهم\n\nبداية كل chapter يسالك اسئلة ويوريك المشكلة و يعلمك حلها خلال ال chapter ويعطيك ال learning objectives\n\nويستخدم الاخبار في فقرة Economics in the news ويخليك تحللها وبعدها يعطيك الاجابة (حاول انك تحل بدون ما تشوف الاجابة لان غير كذا ما تستفيد)\n\nاحيانا يتطرق الكتاب لذكر بعض الاسماء الشهيرة في هذا المجال حديث العهد زي Adam Smith وكتابه The Wealth of Nations و J.S. Mill و Alfred Marshall وغيرهم من كبار المجال هذا\n\nوفي في نهاية ال chapter يعطيك Economic analysis للمشكلة اللي عطاك اياها في بداية ال chapter\n\nبعدها تلقى في شي اسمه ال wrap up قبل ال chapter الجديد بكم صفحة يذكرون احيانا احد كبار هذا المجال ويربطون اسهاماته بالمجال\n\nوايضاً تلقى في ال wrap up يتكلمون مع شخصيات قوية في هذا المجال وعايشين للحين عشان تعمق فهمك في المجال اكثر والشخصيات هذي ضمنها Esther Duflo و Susan Athey و Steven D. Levitt اللي كتب كتاب Freakonomics و ايضا Thomas Hubbard (طبعاً كل واحد راح يكون مربوط باحد ال parts)\n\nال wrap up ما يكون موجود بعد كل chapter لكنه يكون موجود بعد كل part واللي يكون عدة chapters منصفها الكاتب على انها part واحد\n\nمدى فائدته في الناحية التطبيقية\n\nاشوفه احد اهم المواد اللي درستها ان لم تكن اهمها، المادة تعلمك عن العالم اللي حولك وجداً رهيبة\n\nالملخص:\n\nحل ال study plan واقرا الكتاب\n\nالTest bank حق الكتاب هذا تقدر تشتريه من الموقع ذا\n\nMicroeconomics 13th Edition Parkin Test Bank - Test Bank - Solutions Manual - Download\n\nصراحة ما استخدمت ال test bank لان اشوفه طويل بزيادة وال study plan يكفي\n\nدرجات ترم 213 او ال Letter grade cut-offs:\n\n86.5-100. A+\n\n83.5-86.4. A\n\n75.5-83.4. B+\n\n71-75.4 B\n\n64.5-70.9 C+\n\n60-64.4. C\n\n55-59.9. D+\n\n50-54.9. D\n\nاقل من 50 F\n\nCourse Average:\n\n66.454\n\nطبعاً كان عددنا 17 تقريباً ف كانت الدرجات مختلفة بحكم قّلتنا وهذا اللي سبب التغير ال cut-offs الكبير لكن في اثنين جابوا A+ انا وواحد ثاني و واحد جاب A و ثلاثة B+ ف في ناس تجيب درجات اللي عليك تشد وتجتهد وربك يسهلها\n\nوغير كذا انه صارت نكبة في اول ميجر لكل الطلاب مما جعل الاختبار النهائي من 55 بالمية من درجات المادة ( اسالوا طلاب ترم 213 ليش)", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/econ-101-principles-of-economics-i-micro/121027/20", "user": "Don_Quixote_875", "ts": 1661484813000, "tid": 121027, "pn": 20}}', 1661484813000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p820667-econ101', 'stk-opo97', 'ECON 101', 'srcU', '{"html": "major econ 101<br><br>سلام عليكم ياأخ UnKnown<br>انا عند حسن العبندي ومكتوب في السيليبس<br>Tuesday march,22 2011<br>من الساعه 6:30 الى الساعه 8:30<br><br>مبنى 10<br>وذي نسخه من السيليبس<br><br>​<span data-fid=\"stk-f820667-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f820667-0": {"name": "102syllabusECON101.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/9c3c2429e7f5c245c76aa305bdfa000ede7d45478fe294047ec5375dc0566123"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/econ-101/105282/2", "user": "opo97", "ts": 1300645127000, "tid": 105282, "pn": 2}}', 1300645127000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8581-econ101', 'stk-user8581', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f98252", "n": "Dr. Ibrahim M. Algahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "econ 101 term131\n\nالتحضير\n: ورقة تمر على الطلاب وانتبه تحضر واحد لأنه يعتبره غش ولو حصلت منك مرة ثانية على شؤون الطلاب … احيانا ينسى انه يحضر خصوصا في نهاية السمستر لكن لأنه كل كلاس كويز احيانا يحضر بالكويز … الرجال متعاون مع الطلاب واخلاق واذا صار عندك ظرف او مثلا رحلة في آخر يوم دوام يحضرك لكن لازم تكلمه وهو ماراح يقصر …\n\nطريقة الشرح :\nمن الكتاب يمر على الصفحات الي يشوفها مهمة ويسترسل في شرحها على السبورة واذا كان فيها رسم او قانون يشرح لك كيف ومن جات الرسمة والقانون . يشرح المفاهيم والأفكار ويربطها بأمثلة من الواقع ويعطيك قصص و امثلة وتجارب صارت له شخصيا بس عشان تفهم الفكرة بطريقة بسيطة لأن على ما اعتقد هو اعتقد راعي مشاريع او شركة هذا الي حسيته من كلامه ماني متأكد. العيب الوحيد هو إن كلاساته تكون بعد الظهر ويكون مدتها ساة وثلث واحيانا ياخذ خمس دقايق زيادة فتشوف الطلاب بعد نص الكلاس خلاص داخوا وقليل الي يركزون .\nبإختصار تبي تفهم المادة سجل الملاحضات الي يقولوها وتحس يركزها عليها لأنها هي تكون الزبدة من الدرس وهالشي يريحك لأن الكتاب نوعا ما فيه كلام كثير واحيانا صعب تفهم الدرس اذا قريته بروحك وانت ماعندك خلفية عنه .\n\nالكويزات :\nبداية كل كلاس كويز سهل جدا لخمس دقايق و يكون سؤال واحد فقط ويكون غالبا رسمة او عدد واحيانا وسط الشرح اذا كان الدرس مهم يعطيك كويز عليه والصراحة اعتبر هالنوع من الكويزات بونص لأنه يكون توه شارح لك وبس يبي يشوف انت مصحصح معاه ولا . تقريبا اخذنا 20 كويز في السمستر لكن الصراحة هالشي فادنا لأنه كنا ندخل الميجر واحنا اصلا مذاكرين وفاهمين وبس الي نحتاجه مراجعة .\n\nتبي تاخذ فل مارك في الكويزات : وهو يشرح سجل الأشياء يركز عليها ويطول عليها في الشرح\nخصوصا الرسمات + قبل الكلاس افتح الكتاب واحفظ الرسمات , والتعريفات الي تكون على هامش الصفحات .\n\nالمياجر:\nكل ميجر فيه 50 سؤال و عليه 25 درجة ومستواهم بين السهل والمتوسط لكن نصيحة لا تذاكر ليلة الاختبار او تهمل المادة لأن في ناس جابوا العيد في الميجر الأول ووراح عليهم كم قريد . تبي درجة حلوة ذاكر من السلايات + الملاحضات الي كنت كاتبها خلال الشرح وفي النهاية الـ summary الي يكون نهاية الشابتر .\n+ المادة هذي نظرية فالمياجر مافيها حساب او قانونين كثيرة …اللهم يجيب لك تعريفات ورسمتين او 3 ويكون لك على سبيل المثال عند اي سعر و كمية راح يكون هناك equilibrium فإفهم الرسمات وبعض التفاصيل فيها …\n+ الاسئلة ماهي من التست بانك فلاتضيع وقتك في حله .\n\nالفاينلات :\nبحكم إن المادة مياجرها والفاينل مب comprehensive فالفاينل يكون كأنه ميجر ونفس مستواه , اللهم عليه 30 درجة فمذاكرتك له بتكون نفس مذاكرتك للميجر\n\nالقريد النهائي: a\n\nالصوت:الاكسنت ممتاز والصوت واضح لكن ماهو بذيك القوة … فالي ورا يعانون شوي …\n\nإضافات :\nحاليا اشوفه افضل دكتور للـ econ101 والمادة اساسا سهلة لكن ماشاء الله عليه يحاول يبسطها اكثر ودايما يشرح لطلاب الادراة الأشياء المهمة وكيف راح تفيدهم في المستقبل .\nيسوي روحه شوي شديد لكن في الواقع طيب وراح يبين هالشي في نهاية السمستر .\nاذاقال Put your pencil down نصيحة لاتكتب شي لأنه راح يشق الورقة حتى وان كنت تكتب اسمك …هذي يمكن السلبية الوحيدة الي فيه . + يعطي بونصات على اشياء سهلة مثلا يقولك رح لموقع تداول واطبع income statement للشركة الفلانية … واحيانا يسأل والي يجاوب عليه يعطيه بونص\n+ ماعنده هوموركات واذا قال السؤال الفلاني هومورك فقصده انك تحله بس ماتسلمه , لكن اذا قالك جب شيئ معين مثل الـ income statmen او مثال لـ patent فحاول تجيبه لأنه راح يعطيك بونص ويشيل عن كويز لو كنت جايب 0 فيه .\nللأسف مايستخدم البلاكبورد وتواصله مع الطلاب يكون عن طريق القريدر بقروب الواتساب 🤠 !\nاسف على الهذرة لكن للأسف مافي احد كاتب عنه ولا معلومة مع العلم إنه صار له اكثر من 20 سنة في الجامعة وكان الشيرمان للفاينس من 2003 - 2006 لكنه ترك التدريس و مارجع إلا السنة .\n+ هذا إميله\nigahtani@kfupm.edu.sa\nومكتبه B24 - R226\n+\nهذي درجات الطلاب لهذا السمستر ( الكورس ستاندرد)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1316643-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ibrahim-m-algahtani/98252/6", "user": "user8581", "ts": 1389099865000, "tid": 98252, "pn": 6}}]}', 1389099865000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulla_yahia-econ101', 'stk-abdulla_yahia', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f98252", "n": "Dr. Ibrahim M. Algahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "د. إبراهيم القحطاني ]\n\nECON 101 - Term 131\n- التحضير : ما فيه تحضير ، بس كان يحضر بداية السمستر ,\n\n- طريقة الشرح : يشرح على السبورة - شرحه جيد جداً + يعطي أمثلة من الواقع ,\n\n- الكويزات : تقريباً بداية كل كلاس كويز من سؤال سهل عادة ( تقدر تجاوبه لو كنت مركز في الشرح و فاهم ) ، بالنسبة للهومووركات أعطانا هومووركين عبارة عن بحث بسيط - درجات الكلاس وورك 20% تعتمد على الكويزات و الهومووركات ,\n\n- المياجر : متوسطة - 50 سؤال خيارات ,\n\n- الفاينلات : نفس طريقة المياجر ,\n\n- القريد النهائي : B\n\n- الصوت : منخفض نوعاً ما - تتعود عليه مع الوقت ,\n\n- إضافات : الدكتور سهل التعامل و محترم ، و يعطي بونس أحياناً + أنصح فيه و أعتبره أفضل الموجودين في 101 ,", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1321684-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ibrahim-m-algahtani/98252/7", "user": "Abdulla_Yahia", "ts": 1390502467000, "tid": 98252, "pn": 7}}]}', 1390502467000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mhm14-econ101', 'stk-mhm14', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f98252", "n": "Dr. Ibrahim M. Algahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Econ 101 term 132\n\nالتحضير: يحضر الطلاب بالكويز\n\nطريقة الشرح: يبدأ بعرض النقاط الرئيسية للدرس مع مراجعة سريعة لما تم شرحة في الدرس السابق، بعدها يخلي كل طالب يقرأ المصطلحات في الكتاب و يعلق الدكتور عليها و يشرحها، يشرح لك من خلال أمثلة في الحياة و كان الشرح ممتع و يبسط لك المادة بشكل ممتاز\n\nالكويزات: كويز كل حصة، سؤال واحد من الدرس السابق و بعض الأحيان يطلب منك حل سؤال من الكتاب\n\nالمياجر: كل ميجر 5 تشباتر، 50 سؤال اختيار متعدد، الدكتور قبل الميجر يحدد المهم في الكتاب و الأسئلة عادة ما تخرج من النقاط اللي حددها، أسئلة سهلة إلى متوسطة\n\nالفاينلات: تماما مثل الميجر، 5 تشباتر فقط\n\nالقريد النهائي: A\n\nالصوت: منخفض، الأفضل تجلس قدام حتى تسمع\n\nإضافات: أكثر شيء يكرهه لما يشوف طالب مطلع الجوال أو يرن جواله بالكلاس، توصل بعض الأحيان إنه بيطرد الطالب 🙂\n*الملاحظات اللي يكتبها على السبورة مهمة و أنصح الطالب إنه دائما يكتب أي ملاحظة معاه لأنها مفيدة في الكويزات و المياجر\n*وزع علينا ملخصات لبعض التشباتر و كانت مفيدة كثير\n* الدكتور للأسف ما يستخدم البلاك بورد\n* أنصح فيه أخلاقة طيبة و متعاون مع الطلاب و شرحه ممتاز", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1370395-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ibrahim-m-algahtani/98252/8", "user": "MHM14", "ts": 1400929542000, "tid": 98252, "pn": 8}}]}', 1400929542000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10207-econ101', 'stk-user10207', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f98252", "n": "Dr. Ibrahim M. Algahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ECON 101 – Term 141\nما عنده تحضير. (يحضر بالكويز).\nطريقة الشرح ممتازة. يشرح على السبورة الدرس ويكتب نوت رائع. يعبي السبورة شرح ويمسح ويكتب كثير.\nدائماً يربط الشرح بأمثلة.\nنظامه كل بداية كلاس كويز. الكويزات بسيطة من الدرس تبع الكلاس الي قبل.\nالكويزات تكون في أول دقيقة بداية الكلاس. فعشان كذا لو كنت تغيب أو تتأخر بيروح عليك الكويز.\nالكويز عليه 1% من المجموع الكلي. معناتاه أنه يأثر في القريد.\nالمياجر بسيطة وكان متعاون مع الطلاب.\nيعطي بعض الأحيان هوموركات. الهوموركات هذي يجيب نفس الأسئلة نفسها في الميجر وبنفس الأرقام.\nالمياجر كثيره عنده. حوالي 5 مرات بيختبرك مياجر صغيرة عليها 10% وبعض الأحيان 15%.\nيعطي بونصات كثير. بونصات على كويز، في الميجر أسئلة بونص، في الكلاس الي يجاوب بونص، وغيرها.\nالأختبارات سهلة ونفس الوقت يمر كثير على الطلاب إذا احد عنده سؤال.\nقبل أي ميجر أو فاينل يحدد معك الأشياء الي راح تجي بالإختبار!\nالكويزات كتابية. المياجر والفاينل إختيارات بس مافيها لف ودوران. واضحة.\nإذا ودك تفهم وتحل المياجر، أفهم معه وأكتب النوت.\nلازم تجيب معك الكتاب لأنه يخلي الطلاب يقرون المصطلحات بالكتاب وهو يعلق عليها.\nالفاينل عنده خفيف. 3 شباتر ويحذف منها صفحات كثير. بس تذاكر 15 تقريباً صفحة للفاينل.\nيعطي كلاس مراجعة للفاينل.\nمعتمد على الكتاب بشكل كبير. لكن على نهاية الترم يشرح مثلاً شبتر بعيد بعدين يرجع للي قبل وكذا مع كم شبتر.\nالـ A+ عنده من 95.\nصوته ضعيف. لغته الإنجليزية ممتازة.\nيهزء الطلاب الي مايجاوبون على سؤاله.\nممنوع عنده تلعب بالجوال أو يرن الجوال أو تسولف مع واحد ثاني.\nعادي تستخدم الجوال إذا كنت بتصور النوت المكتوب على السبورة.\nالكلاس عنده لازم تتكلم إنجليزي.\nما يستعمل البلاكبورد طول الترم إلا على نهايته. يرسل فيه نتائج آخر الإختبارات.\nيتكلم كثير بأشياء وقصص متعلقه بالدرس.\nدكتور أكثر من رائع. أنصح به.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1422225-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ibrahim-m-algahtani/98252/10", "user": "user10207", "ts": 1422234096000, "tid": 98252, "pn": 10}}]}', 1422234096000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-jacksparrow-econ101', 'stk-jacksparrow', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f98252", "n": "Dr. Ibrahim M. Algahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا حاليا ادرس معه ECON 101 في ترم 152\n\nالتحضير : ما فيه تحضير لكن في بوب كويز كل كلاس\n\nطريقة الشرح : الدكتور حريص جداً على ان الطالب يجيب معه الكتاب و ما يستخدم الكمبيوتر ابد في الكلاس, التعاريف اللي يخلي الطلاب يقرونها حددها لأن فيه احتمال كبير تجي الكويز الجاي\nالكويزات : كل كلاس يكون فيه بوب كويز عليه درجة و يكون سهل غالبا \" انا عن نفسي اجي قبل الكلاس بنص ساعة و ابدأ اذاكر و غالبا احاوب صح\" طبعا مدة الكويز دقيقة و صدقوني اهم شي عنده الكويزات لأن عليها 25% من الكورس !!\nالمياجر:ميجرين كل واحد 25% و يعطي بونص فيها تصل الى 3 درجات, المياجر مرات تجي TB و مرات تجي من احد المواقع اللي مرسلها على البلاك بورد < (زي ما يقولون لي اللي درسوا معه) و اللي شفته انا انه جاب من الشرح اللي يقوله في الكلاس.\nالفاينلات : عليه 25% و مو comprehensive يعني اللي تدرسه ما راح تذاكره ثانية 👍\nالصوت: الصوت ضعيف نوعاً ما\nإضافات :\n1)الدكتور شديد من ناحية اللغة الانجليزية و ممكن يهاوشك اذا تكلمت عربي\n2)يعطي كويزات بونص و الى الميجر الثانس ما عطانا الا هوموورك واحد و سهل جداً\n3) درجة الكويزات من 25% و يعطينا اكثر من 25 كويز اذا زدت عنها فهي بونص في المياجر\n4)مسألة انك تنشغل بالجوال باستثناء التصوير بيهزئ فيك\n5) يسمح لك بعد الكويز انك تسحب على الكلاس\n6) الدكتور متفهم لأبعد درجة من ناحية الظروف الشخصية للطالب\n7) يستغل الوقت كله و مستحيل يطلع قبل الوقت\n8) المادة للي ما يعرف مياجرها و فاينالها مو كومن فتفرق جداً جداً من مدرس الى اخر و اذا بتشد في الكويزات فور شور بتاخذ قريد B+ و فوق\n\nانصح اللي بينزل ينزل عنده حتى لو احتاج يأخرها كم ترم لأن باقين الدكاترة سيئين الى ابعد حد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1445961-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ibrahim-m-algahtani/98252/14", "user": "JackSparrow", "ts": 1459907479000, "tid": 98252, "pn": 14}}]}', 1459907479000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kitkat-econ101', 'stk-kitkat', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f98254", "n": "Dr. Usamah Ahmed Uthman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور نزلت معاه 091 … الرجل ما شاء الله موسوعه من العلم … صحيح اختباراته لحاله بس الماده عنده آفرج وهذا لمصلحة الطالب … ويقول انا بخيركم على دراسة الكتاب القديم او الجديد اذا تبون القديم تلاقون النوت جاهزه بالويب بيج حقتي واطبعوها وتكفيكم لانها شامله … والكويزات متوسطة… والاختبارات ايضا متوسطة تميل الى الصعوبة …\n\nانصح فيه للي يبي يطلع من الايكون 101 فاهم وهذا لمصلحته لانه بـ 202 ما عانيت ابدا بالفهم … لانه كان يشرح لنا كل شي وكان يتكلم عن 202 وكان يربطهم لنا …\n\nملاحظه: الدكتور اسامة f تغير والسب والشتم اللي صار عليه من بعض اخواننا الطلاب في المنتدى وخارج المنتدى اللي يهديهم قبل التغيير !", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p749690-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-usamah-ahmed-uthman/98254/11", "user": "KiTKaT", "ts": 1293026299000, "tid": 98254, "pn": 11}}]}', 1293026299000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10665-econ101', 'stk-user10665', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f98254", "n": "Dr. Usamah Ahmed Uthman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذت معاه ECON 101 Term 161\nبصراحة الدكتور متمكن من المادة بشكل كبير ، لكن عيبه انه ما يعرف يتعامل مع الطلاب و ما يعرف يوصل معلومة\nبمعنى ، انه يكلم طلابه و كأنهم علماء اقتصاد او فاهمين المادة مثله ، اسامة عثمان اذا بيدرس المفروض يحطونه بكورسات متقدمه او مع ماجستير\nانه يدرس ايكون 101 غلط\n\nالتحضير : اوقات ببداية الكلاس اوقات باخره و في الغالب ما يحضر\nطريقة الشرح : الصوت و الآكسنت ممتازين ، لكن زي ما ذكرت اوقات يتعمق بشكل احنا ما نفهم معه ، خصوصاً اول شهر بالكورس ماحد كان فاهم وش يقول\nالكويزات : اسئلة MC احياناً يجيبها من الـ study guide اللي تشتريها من الجمعية نسخ لصق ، او يجيب اسئلة من عنده دمار\nالمياجر: اسئلة MC كلها من عنده و صعبه جداً ، الافرج للميجر الاول كان 57% و الثاني 62%\nالفاينلات : نفس المياجر اسئلة اختيارات و صعبة جداً و ما طلع لنا درجاتها ولا نعرف كم الافرج ولا شيء ، اخر شيء شفناه هو القريد فقط\nالقريد النهائي: C\nالصوت: واضح\nإضافات : الدكتور ما يعطي قريدات ابداً ، اعلى واحد بالسكشن اخذ عنده B وانا اشوفه يستحق اكثر ، و الباقين C و D ، عشان كذا انا انصح ماحد ينزل عنده لانه بيخسف بأم المعدل\nغير كذا الدكتور شديد بالكلاس لا تنشغل بالجوال او بالكلام او حتى بالنظر للنوته على الدرس !! يوقف المحاضره و يجلس يقول مو وقت انك تقرأ النوته 😐", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466580-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-usamah-ahmed-uthman/98254/35", "user": "user10665", "ts": 1484809186000, "tid": 98254, "pn": 35}}]}', 1484809186000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-aziiz99-econ101', 'stk-aziiz99', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f98254", "n": "Dr. Usamah Ahmed Uthman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "econ101-171\n\nقبل انزل معه صوروه لي انه افضل دكتور شرح و هالكلام موب صحيح\nما نختلف ان شرحه جيد بس موب شي قوي مرره فيه كثير درسوني شرحهم افضل\nالدكتور ما عنده أي احترام للطالب عادي يمسح فيك الأرض اذا سالك ولا جاوبت\nكان ظالمني في الفاينل قريد لما سالته عن السبب ما بقى شتيمه ما شتمني فيها و طردني من مكتبه\nكانت درجاتي في المياجر من الأوائل عالدفعه و عطاني c", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1502348-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-usamah-ahmed-uthman/98254/36", "user": "aziiz99", "ts": 1542144148000, "tid": 98254, "pn": 36}}]}', 1542144148000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kbsc-econ101', 'stk-kbsc', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f98254", "n": "Dr. Usamah Ahmed Uthman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور :\n\nاسامة عثمان\n\nالمادة: *\n\nECON 101\n\nطريقة الشرح : *\n\nالرجل فاهم الاقتصاد لكنه يستخدم مصطلحات صعبة الفهم يشرح من النوت حقه ولا يلتلفت إلى الكتاب إلا نادرا\n\nالكويزات :\n\nأغلبها من study guide وقليل من مصادر أخرى\n\nالمياجر/ميد:\n\nمن صعبة إلى صعبة جدا ( كومن ) أكثر الاسئلة من خارج النوت\n\nالفاينل :\n\nمن صعبة إلى صعبة جدا ( كومن ) أكثر الاسئلة من خارج النوت\n\nطريقة التحضير :\n\nنهاية الكلاس\n\nالقريد النهائي الخاص بك :\n\nC\n\nاضافات:\n\nنزل المادة صيفي لأنك تطلع فاهم وبقريد حلو", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1507365-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-usamah-ahmed-uthman/98254/37", "user": "KBSC", "ts": 1552817590000, "tid": 98254, "pn": 37}}]}', 1552817590000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-yousefli-econ101', 'stk-yousefli', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f167104", "n": "Dr. Fahad Al-Subaie", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Econ 101 - 181\n\nالتحضير : على المزاج مره يحضر ومره لا\n\nطريقة الشرح : رغم كل اللي يذمونه للامانة م كان سيء كان متوسط ف كان يشرح لك المنهج ويطلع بره ويعطيك معلومات عامة جدا تفيدك ويربط لك المنهج بالحياة بحيث تشوف الدنيا صح ويوريك اهمية الاقتصاد في البلد واظن هذا فايدة الكورس اساسا … يبين لك الحقائق ولو تفكر في الدرس وتفكر في اللي قاعد يشرح لك تشوف انه اصلا قاعد يربط لك الاحداث بحيث ما تنساها والاغلب يقولك رح عند عثمان عشان شرحه\nللامانة انا كنت مرتاح معاه دكتور فهد السبيعي بالشرح وكان يمشي بنوتة اسامة واذا خذه الوقت من الربط يبدا يمر ع نوتة ذاك بسرعه\nلكن للامانة م ندمت اني نزلت معه ع رغم قريدي م كان بالمستوى وما كان اهو السبب … السبب في اللي يحط الاسئلة\nف للامانة لو رجع الزمن وحطو لي بداله كل الدكاترة حقين الايكونمي م بختار غيره … يخليك تفكر صح ويوريك الاقتصاد وكل شيء كيف ماشي وعلى رغم البعض يقولك عنده ماجسيتير اقتصاد وبكالريوس فيزياء ف اهو اللي ماسك استثمارات الجامعة ف شوف وين الانسان واصل … تفكيره سليم وانسان محترم لما تمشي معاه ف لاحد يخربط عليك ويذمه بسبة اسلوبه اهو كذا مافيه حد يجيك كامل والكامل وجهه\n\nالكويزات : كان واجبات وكل اسبوع واجب لكن يعلمك كيف تبحث في الكتاب عن الاجابة ويدف كثير بعد ويسلك كثيرر ع رغم احيانا يعطيك وقت غلط لكن يعلمك انه الحياة ماهي سهله وان انت طالب مهمتك تذاكر مو تلعب فيوضح لك اساسا هدفك من دخولك الجامعة فدكتور احترمه كثير ومستحيل انساه\n\nالمياجر: كومن وصعبة بسبة اسامة عثمان هو اللي يحط الاسئلة\n\nالفاينلات :كومن وصعبة بسبة اسامة عثمان هو اللي يحط الاسئلة\n\nالقريد النهائي: B+\n\nالصوت: واضح\n\nإضافات :\n\nاخلاقه للامانة هي السبب اللي يخلي الاغلب يكرهه انسان عنده نظام معين طبقه وامورك في السليم\nاما تجلس تلف وتدور تروح عليك غلطة … ف مثلا يقول لاحد يسئل في الميد نهائيا حتى لو في شيء غلط\nلو في غلط بيكنسله لو ما نبهوكم عليه\nيجي لك واحد ويسئل وصح فيه غلط … لكن نظامه واضح وسفل فيه ولا سمع له حتى ويوم لقوا انه في غلط\nلكن الناس تحكم ب اسلوبه بسبة موقف ويجيك يسفل فيه\nواي طالب رسب في الايكون بسبة اهماله م له دخل الدكتور في شيء\nيجيك طول الترم يتلعب م يذاكر وفي النهاية يقولك الدكتور م دفني والله لو انك تذاكر ولو شوي تنجح\nصح الاسئلة نار لكن النجاح م كان صعب كان انزل من الافرج ب ٦ الى ٧ احيانا … فمعناها انت انزل من الافرج ف انت اساسا\nما مهمل … كثير ناس كانت تلعب ونجحت بسبة تذاكر شوي … يشوف نفسه ضايع ويسحب ع المادة ويرسب ويقولك الدكتور السبب\nويجي في التقييم ويظلم الدكتور بسبة انه م زوده أو انه اخلاقه…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1514145-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fahad-al-subaie/167104/12", "user": "yousefli", "ts": 1566765168000, "tid": 167104, "pn": 12}}, {"id": "stk-dr-f98254", "n": "Dr. Usamah Ahmed Uthman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ECON101\n\nأسامة عثمان\nالأخلاق عالية\nالشرح بذمة وضمير\nالكوزات ٤ ستادي قايد\nالمياجر كومن إذ كان موجود بتكون صلخ ما تفرق\nالتحضير على الوقت ولا يمديك تطلع من الكلاس لو، صار الي صار\nممنوع استخدام الجوال و شرب الماي في الكلاس\nيحب الاسالة البولسي\nسريع الرد في الايميلات و يجي في الوقت حق الاوفس اور", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1516867-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-usamah-ahmed-uthman/98254/38", "user": "yousefli", "ts": 1573405353000, "tid": 98254, "pn": 38}}]}', 1566765168000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-nawafmkz-econ101', 'stk-nawafmkz', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f98254", "n": "Dr. Usamah Ahmed Uthman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "econ101-191\nالتحضير : نهاية كل كلاس بالأسماء، ما يسجل ليت لكن يعطي الواحد محاضره عن التأخير والاحترام مع أنه دايم يجي متأخر.\nطريقة الشرح : الشرح من النوتة -النوتة مختصرة جدا جدا-، الدكنور فاهم لكن شرحه ادفانس وغير مناسب اطلاقا للي اول مرة يدرسون اقتصاد، يتقبل الأسئلة وما عنده مانع يعيد الشرح، يجيب أمثلة كثيرة جدا جدا -عن نفسي ما أفهم إلا من الأمثلة والسوالف- غالب الكلاسات مملة جدا. في النص الأخير من السمستر صار يقول خلوا جولاتكم على جنب\nالكويزات : في البداية الغى الكويزات لكن رجعها، 6 كويزات ثلاثة منها نسخ لصق من الستدي قايد و3 من عالم آخر، ما يحذف ولا يعطي بونص.\nالمياجر: صعبة بالمجمل الأول كان قريب من النوتة وشرحه والثاني أسئله مجمعها لكن ماهي على أسلوبه\nالفاينلات : صعب وكثير أسئلة تكون حول المواضيع اللي يسولف عنها في الكلاس\nالقريد النهائي: C\nالصوت:واضح والاكسنت ممتاز جدا\nإضافات :يرد على الايميلات، ويأجل الكويزات إذا الأغلبية طلبوا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518440-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-usamah-ahmed-uthman/98254/39", "user": "NawafMKZ", "ts": 1577656343000, "tid": 98254, "pn": 39}}]}', 1577656343000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khdsa2022-econ101', 'stk-khdsa2022', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f98254", "n": "Dr. Usamah Ahmed Uthman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "BY WHATSAPP\nاسم الدكتور : اسامة عثمان\nالمادة: Econ 101\nالفصل الدراسي:191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : نهاية الكلاس وطبيعي انك تتأخر على الكلاس اللي بعده عشان التحضير\nطريقة الشرح : شرحه حلو اذا كنت مركز طول الكلاس وجالس قدام، اما اذا كنت ورى او تأخرت 5 دقايق اعرف انك ماراح تفهم شي\nالكويزات : اذا جاب من study gide راح تضمن كامل اما اذا من بره ال study gide ماراح تفهم شي وراح تشوز كامل الكويز\nالمياجر: صلخ، عذاب، يعني اذا ماغشيت اعرف انك جايب العيد وطبيعي تضمن بس سؤال واحد من ٤٠ سؤال\nالفاينلات :الفاينل نفس الميجر ضمنت بس سؤالين من ٦٠ سؤال\nالقريد النهائي: F\nالصوت: ممتاز\nإضافات : دائما هو الكوردنيتر تبع econ 101 وعنده نوتات ما يفهمها الا الدكتور، افضل حل انك تزلها في الصيفي عند فضلول", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518839-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-usamah-ahmed-uthman/98254/40", "user": "Khdsa2022", "ts": 1578295182000, "tid": 98254, "pn": 40}}]}', 1578295182000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-f.a.b-econ101', 'stk-f.a.b', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f98268", "n": "Dr. Reza Fathollahzadeh Aghdam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير : غالبا\nطريقة الشرح : سلايدات طبعا وغالبا يشرح الرسم بالسبورة\nالكويزات :اون لاين ولك محاولتين\nالمياجر:كومون\nالفاينلات :كومون\nالقريد النهائي:c\nالصوت:افضل واحد بالايكون 101 و202\nإضافات ماي ايكون لاب احرص عليه حتا لو ماقال عليه شي ترا ينتبه له وحل جميع التشباتر", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p739293-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-reza-fathollahzadeh-aghdam/98268/2", "user": "F.A.B", "ts": 1290810130000, "tid": 98268, "pn": 2}}]}', 1290810130000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-1x1_1-econ101', 'stk-1x1_1', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f98275", "n": "Dr. Muhammad Saifur Rahman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذت معاه ايكون101 سمستر 111\n\nالتحضير: ما يحضر\nطريقة الشرح: سلايدات, قصص واحداث وامثله متعلقه بالدرس\nالكويزات: سهله متعدده الاختيارات نسخ ولصق من الموقع الي تسويه في الهوموورك, بعض الكويزات اونلاين تسويها في نفس الموقع\nالمياجر والفاينل: كومون, اغلب الاسئله والافكار نفسها الي بالهوموورك او اسئله المراجعه الي كان يعطينياها\nالقريد النهائي: A\nالصوت: اللكنه ممتازه ويبدولي انه من الهنود الي لغته الام انقليزيه, صوته واضح\nإضافات: يعجبني انه كان يستخدم الموقع حق الكتاب والي فيه اسئله كثيره مفيده, وكان يختار افضلها للهوموورك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1024745-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-muhammad-saifur-rahman/98275/16", "user": "1x1_1", "ts": 1334789362000, "tid": 98275, "pn": 16}}]}', 1334789362000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5755-econ101', 'stk-user5755', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f98275", "n": "Dr. Muhammad Saifur Rahman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا طالب اندستريال … واخذت معه econ 101 الكتف …\nاقولها وبكل صراحة … اني حبيت الاقتصاد منه …\nوصرت مهتم بالمواضيع الاقتصادية واحب اتابعها …\nدكتور فعلا يدمج لك بين الجو الاكاديمي والتطبيق الواقعي.\n\nصوته واضح ولهجته واضحة … التحضير مايحضر ابدا الا بايام الكويزات والهوموركات\nكويزاته وهوموركاته عبارة عن ملتبل تشويز\nوالفاينل كومن …\nوينزل لك قبل كل كويز وميجر وفاينل … سامبل يعطيك فكرة عن الماتيريال والاشياء المهمة فيه\n\nالقريد النهائي a+ بجدارة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1224160-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-muhammad-saifur-rahman/98275/19", "user": "user5755", "ts": 1368952410000, "tid": 98275, "pn": 19}}]}', 1368952410000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-practice-econ101', 'stk-practice', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f98275", "n": "Dr. Muhammad Saifur Rahman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "احسن دكتور ممكن يمر عليك !!\n\nانا اخذت معاه ايكون101 وذحين منزل ايكون102 معاه برضو ترم 131\n\nدكتووووور بطططططططططططططططططططل\n\nمافي تحضير نهائيا ولا يعترف فيه\n\nشرح متعوب عليه واسلوبه حلو ويشدك\n\nكويزات نسخ لصق من التيست يانك\n\nحبوب وكلاسه ما ينمل منه نهائيا\n\nما يدف في القريدات , حقك بالملي\n\nالله يسعده ويوفقه دنيا واخره", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1251702-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-muhammad-saifur-rahman/98275/20", "user": "Practice", "ts": 1375748601000, "tid": 98275, "pn": 20}}]}', 1375748601000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-creative-guy-econ101', 'stk-creative-guy', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f98275", "n": "Dr. Muhammad Saifur Rahman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "رحمن وما أدراك ما رحمن\n\nالتحضير : مايحضر أبدا\nECON101\nطريقة الشرح : شرح ممتع, يتقبل الأسئلة, ويفرح كثير إذا سألته ويحاول يخلق نقاش بين الطلاب. يشرح باستعمال الأمثلة, وبعض الأمثلة ترسخ في الذهن وماتنساها ختى في كورسات الأيكون الي بتاخذها قدام\nالكويزات : كويزات سهلة\nالمياجر: سهلة نوعا ما\nالفاينلات : أيضا سهل\nالقريد النهائي: A+\nالصوت: جميل لغته الإنجليزية بلكنته الهندية 🙂\nإضافات : يدف إذا كلمته ف الأوفيس\n\nطبعا رحمن يعجز اللسان والقلب وكل حته أن توصف تميز هالبني آدم\n\nملك ملك ملك ملك ملك ملك ملك ملك\n\nأنصح طلاب الانجنير الي بينزل الكتيف ينزل Econ101 عند رحمن", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1251765-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-muhammad-saifur-rahman/98275/21", "user": "creative-guy", "ts": 1375790258000, "tid": 98275, "pn": 21}}]}', 1375790258000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bu_nawwaf-econ101', 'stk-bu_nawwaf', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f115367", "n": "Dr. Fazlul Miah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت عنده ايكون 101 أول ترم له يدرس\n\nالتحضير يومي وأحيانا يدقق ع التأخير\n\nالكويزات يحذف أسوء واحد\n\nلا يعترف بنظام الأب قريد بتاتا حتى لو كنت جايب 84 تعتبر b\n\nوقريدات طلابه تشوف كم B و B+ على كم +D على كم C+ و C وفي الترم اللي كنت فيه ثنين أو واحد جاب A عنده لاكن الرجال مجتهد جدا\n\nيعني بالعربي درجاته متوزعه كويس\nالشرح في ال101 كان ماشي حاله (مب توب) لأنه كان سهل نسبيا وما أدري عنه بالفايننس\n\nأخلاقه كويسة\n\nصوته واضح ولهجته مقبوله\n\nملاحظات : ما أعطى a+\nما أعطى f\n\nحاولت أضبطه بالأوفيس ما قدرت", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1255162-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-fazlul-miah/115367/17", "user": "Bu_Nawwaf", "ts": 1377392457000, "tid": 115367, "pn": 17}}]}', 1377392457000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faris_alali-econ101', 'stk-faris_alali', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f115367", "n": "Dr. Fazlul Miah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ECON 101 في 173\n\nالتحضير : يحضر قي نهاية الكلاس واذا دخلت قبل نهاية الكلاس بخمس دقايق بيحضرك وهو متهو داري انك توك جاي\n\nطريقة الشرح : يفتح السلايدات و يقرأ منها بس غالبا يكتب فالسبورة واذا عندك نوتة اكتب وراه الاشياء الي تحسه انت ممكن تجي فالميجر\n\nالكويزات : سهلة و يحط صح أو خطأ كثير اذا المتيريال قليل عشان يكمل العشرة أسئلة.\n\nالمياجر: نفس طريقة الكويزات خيارات و صح أو خطأ ( اسئلة الصح أو خطأ تكون من الكلام الازرق الغامق الي من الكتاب)\n\nالقريد النهائي: B\n\nالصوت: يجيب النوم و مرات يسرح و يتكلم وهو يطالع من الدريشة لذلك اذا انت من نوعية الطلاب الي لازم الدكتور يقولك شيل الجوال ولا تكلم صاحبك و انتبه معي … هالدكتور ما بيصلح لك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1498210-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-fazlul-miah/115367/19", "user": "Faris_Alali", "ts": 1535364627000, "tid": 115367, "pn": 19}}]}', 1535364627000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_182-econ101', 'stk-_182', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f115367", "n": "Dr. Fazlul Miah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ECON101-173\n\nالتحضير: آخر المحاضرة، ما يركز على المتأخرين (غالبًا)\nطريقة الشرح: سلايدات، يكتب على السبورة إذا لزم ويضرب أمثلة لتوضيح الفكرة\nالكويزات: يعطي كويز بعد نهاية كل تشابتر، 10 أسئلة خيارات وسهلة جدًّا إذا كنت مركز معه\nالمياجر: خيارات وصح أو خطأ، برضو المستوى سهل إذا كنت فاهم معه\nالفاينلات: نفس المياجر\nالقريد النهائي: +A\nالصوت: واضح بس هادي، ممكن أول محاضرتين ما تتعوّد بالذات إذا كنت تفضّل الصوت المرتفع\nإضافات:\n\n- منضبط في ساعاته المكتبيّة، ومتجاوب على الإيميل\n- الدكتور جدًّا متعاون داخل وخارج المحاضرة، يحاول يفهّم الطلاب قد ما يقدر ويضرب أمثلة كثيرة لتوصيل الفكرة، ومتعاون جدًّا وقت الساعات المكتبية\n- بداية الدراسة كان الدكتور يسرح شوي وصوته هادي وهو يدري، كان يقول اعذروني بس نومي جدُّا سيّئ، وفعلًا لاحظت بعد فترة أنه أصبح أكثر تفاعلًا< كنّا متفهّمين بحكم أنّ الدراسة كانت بالصيف والمحاضرة الساعة 8 صباحًا\n- يعطي نشاطات صفّيّة من فترة لفترة، يقسّم الطلاب إلى مجموعات من 3-5 طلاب ويخليهم يحلّون سؤالين، مسموح الاستعانة بالجوّال أو أي وسيلة أخرى\n- نصيحة مجرّب، إذا كان الدكتور يحط أسئلة الاختبار فلا تعتمد على السلايدات (وهو بنفسه يقول هالكلام)، اقرأ الكتاب، صحيح أنّ الصفحات كثيرة والكلام طويل، لكن بتدخل الاختبار وأنت واثق (غير أنك بتستفيد!)\n\nأنصح فيه بأي كورس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1506590-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-fazlul-miah/115367/20", "user": "_182", "ts": 1551435267000, "tid": 115367, "pn": 20}}]}', 1551435267000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-saleh_kn-econ101', 'stk-saleh_kn', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f115367", "n": "Dr. Fazlul Miah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ECON 101 - 201 Online\n\nالتحضير : ما قد حضر أبدًا، بس يمكن مرتين طول السمستر قام ينادي بعض الأسماء من الطلاب عشان يتأكد انهم موجودين ويسأل\n\nطريقة الشرح : يشرح على سلايدات ويكتب عليها بالماوس وما تفهم وش كاتب ف كان ياخذ وقت طويل عشان يكتب\n\nالكويزات : ثلاث كويزات، الأول كان كومن من شين بو “الكوردينيتر” والباقي من فضلول\nبالنسبة للكويز الأول كان متوسط، وسؤال واحد كان صعب\nالكويز الثاني كان من فضلول وكان سهل بالنسبة لي\nالكويز الثالث كان من فضلول وكان صعب للأمانة وأغلب الطلاب “إذا مو الكل” جايب تحت ال5 من 10\n\nالمياجر: كان ميد تيرم واحد وكان متوسط الصعوبة\n\nالفاينل : متوسط الصعوبة\n\nالقريد النهائي: الدكتور هذا أعطيه C+\n\nالصوت: صوته واضح لكن يجيب النووووووووووووم مررة ما كنت أقدر أركز معه أبدًا وما قد ركزت معه في ولا محاضرة\nعشان تعرف قد ايش هو يجيب النوم بعض الشباب من الطفش كانوا يلعبون أمونق أس وقت الكلاس 😀\n\nإضافات : الدكتور بداية الترم كان حبيب مرة وضبطني في الكويز الأول اللي كان من الكوردينيتر وأتوقع ضبط الكل، لكن كان عندنا 6 واجبات للأمانة تصحيحه سيء مرة وما تدري ليه يعطيك الدرجة ويحطها من راسه، وكان عندنا قروب وورك 6 طلاب يشرحون موضوع من الكتاب ونفس الشي تصحيحه سيء وكان متذبذب ونقص البعض مع ان شرحهم كان ممتاز. لكن نهاية الترم فصل علينا وصار عصبي بدون سبب وآخر كويز كان صعب مرة مثل ما قلت لكم فوق.\n\nإذا بتنزل هالمادة السمستر الجاي ما عندك الا هو وشين بو، وعلى حسب كلام طلاب شين بو انحش منه ولا تنزل عنده، فلذلك فضلول يعتبر جيد إلى حد ما وأفضل من شين بو", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527756-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-fazlul-miah/115367/25", "user": "Saleh_KN", "ts": 1610277694000, "tid": 115367, "pn": 25}}]}', 1610277694000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-paco-econ101', 'stk-paco', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f115367", "n": "Dr. Fazlul Miah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(Econ101 - 201 (Online\n\nالتحضير : ما يحضر\n\nطريقة الشرح : طول المحاضرة على نفس السلايدة ما يغيرها يكتب عليها بخط مو واضح\n\nالكويزات : اختبرنا 3 الاول كان رتن وكومن الثاني والثالث mcq من الدكتور (الثاني كان سهل والثالث متوسط)\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: C+\n\nالصوت: واضح بس انه بطيئ ويجيب النوم\n\nإضافات : بالنسبة للتصحيح فما قصر بالكويز الاول بس الواجبات يرصد الدرجة وما تعرف ليش ووش اخطائك\nوبالنسبة للبروجكت ما كان عنده معايير يقيم على اساسها والبعض انخسف فيها وما اظن اعطى احد +90%", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527762-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-fazlul-miah/115367/26", "user": "Paco", "ts": 1610288410000, "tid": 115367, "pn": 26}}]}', 1610288410000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hussain_hd-econ101', 'stk-hussain_hd', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f167104", "n": "Dr. Fahad Al-Subaie", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ECON101 - T191\n\nالتحضير: بداية كل كلاس مرات يحضر ومرات لا، على حسب مزاجه لكنه كثير مرات ماحضر وأحيانا يكنسل الكلاس سواها تقريبا ٥-٦ مرات، كان عنده قانون للمتأخرين اذا يبون يحضرهم يخسرون ١٪ من القريد النهائي او يدخلون وهم غياب بالكشف، لكن مافي خصم بس DN بعد ٥ غيابات.\n\nطريقة الشرح: شرحه ماهو شيء بصراحة واغلبه سواليف مربوطة بالسياسة وقرارات الدول، كماتيريل للمادة مارح ينفعك لكن وش تسوي، في البعض وجد هالسوالف ممتعة لكن انا وجدتها مملة ماتخلي الكلاس يمشي، يقرأ من نوتات أسامة اللي وقتها كان الكوردنيتر ويشرح اشياء بسيطة منها.\n\nالكويزات: ٦ كويزات مرة سهلة اذا قدرت تدخل على Dashboard موجود كرت بكتاب المادة تكشط كود وتدخل على موقع الكتاب وتلقى اسئلة اختبار يجيب منها كوبي بيست ٥ اسئلة اختيارية.\n\nالمياجر: كومن، في ميجر ماحط اسئلة فيه وصار اصعب بسبب أسامة بشكل عام هو يحط اسئلة سهلة شوي ٥ اسئلة مثلا حتى يساعد الطلاب يجيبون درجات.\n\nالفاينلات: كومن.\n\nالصوت: متوسط.\n\nالقريد النهائي: C مثل ماهو يحب يذكر الطلاب فيها قبل بداية الكورس.\n\nإضافات: الدكتور هذا ميزته انه يكنسل كلاسات احيانا، وأحيانا مايحضر، والكلاس وورك كان بس كويزات ف كان مضمون، لا يشوفك على جوالك بس، على الاقل اذا احترت بينه وبين أسامة عثمان انصحك فيه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1519719-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fahad-al-subaie/167104/15", "user": "Hussain_HD", "ts": 1580826189000, "tid": 167104, "pn": 15}}]}', 1580826189000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m_of_rivia-econ101', 'stk-m_of_rivia', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f167104", "n": "Dr. Fahad Al-Subaie", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Econ 101 - 201\nالدكتور فهد السبيعي كان اخر ترم له 201.\nما اقول الا معوضين ياللي مادرستو عنده فاتك دكتور اسطورة من الاخرر.\nالقريد النهائي: A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527914-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fahad-al-subaie/167104/16", "user": "M_of_Rivia", "ts": 1610803775000, "tid": 167104, "pn": 16}}]}', 1610803775000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9921-econ101', 'stk-user9921', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f175796", "n": "Dr. Mustafa Ba Biker", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Econ 101 Term 161\n\nهذا أول ترم له في الجامعة ، يشتغل في أرامكو وموجود هنا بارت تايم\n\nالتحضير :\nورقة التحضير تمر على الطلاب في آخر المحاضرة ، ما يدقق ع التأخير لو باقي ع النهاية 5 دقايق\n\nطريقة الشرح :\nشرحه ممل بكل معنى الكلمة ، يفتح البوربوينت ويلقي كلامه بنغمة واحدة\nأحياناً يطوّل على السلايد الواحد فوق العشر دقايق ، وأحياناً يحرق الشابتر في محاضرة وحدة\nما يحل مسائل ولا شي والمصطلحات الجديدة ما يوضّح معناها\n\nالكويزات :\nكان يعطينا كويزات قبل المياجر والفاينل عشان نعرف طريقة أسئلته بس ( يصحّحهم في الكلاس بشكل جماعي)\n\nالمياجر:\nكل ميجر كان 5 شباتر والأسئلة كلها TB\n\nالفاينلات :\nهو الوحيد اللي الفاينل عنده Comprehnsive ، طلابه هم الوحيدين اللي يذاكرون 15 شابتر ، الأسئلة كلها TB ( MCQs , TF )\n\nالصوت:\nواضح ولكن عيبه المصطلحات الجديدة اللي ما نعرفها وهو ما يوضّحها\n\nالقريد النهائي:\nD عشان أن أسئلته TB بس\n\nإضافات :\nأهون من غيره", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466490-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mustafa-ba-biker/175796/2", "user": "user9921", "ts": 1484683378000, "tid": 175796, "pn": 2}}]}', 1484683378000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-jafar_15-econ101', 'stk-jafar_15', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f175796", "n": "Dr. Mustafa Ba Biker", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Econ 101-162\n\nالتحضير : يومي عن طريق ورقة يمررها ، ومايهتم بالتاخير ابدا\n\nطريقة الشرح : يفتح السلايدات ويتكلم بشكل متواصل وتوصيل المعلومة سيء صراحة\n\nالكويزات : من التست بانك\n\nالمياجر: نفس الشي تست بانك\n\nالفاينلات : تست بانك وكومبرهنسف\n\nالصوت: صغيييير\n\nإضافات : الدكتور محترم جدا ومتساهل وقابل للنقاش ومرن في حدود المعقول ، يتساهل في مواعيد المياجر والكويزات بشكل عام الدكتور كويس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474060-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mustafa-ba-biker/175796/5", "user": "Jafar_15", "ts": 1496066251000, "tid": 175796, "pn": 5}}]}', 1496066251000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-stallion-econ101', 'stk-stallion', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f175796", "n": "Dr. Mustafa Ba Biker", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ECON 101 -T241\n\nالتحضير : ورقي كل كلاس بعد نص الكلاس تقريبا\nطريقة الشرح : يفتح السلايدات ويشرح منها وشرحه شبه قراءة من السلايدات يعني صعب تستفيد\nالكويزات : متوسطة الى صعبة تشبه الستدي بلان والتست بانك\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: C\nالصوت: واضح\nإضافات : الدكتور يسافر كثير يعني تتكنسل محاضرات فجأة او ما يحضر او تصير عن بعد بحكم انه مستشار في ارامكو فممكن يجحفلك في سالفة اللكتشر, الدكتور “اذا رد عليك” فهو متعاون وخلوق جدااااا ويساعد الطلاب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1538707-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mustafa-ba-biker/175796/6", "user": "Stallion", "ts": 1735915090294, "tid": 175796, "pn": 6}}]}', 1735915090294, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9840-econ101', 'stk-user9840', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f177579", "n": "Dr. Chen Bo", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ECON 101- T 171\nها انا اعود لتقييم هذا الانسان غريب الأطوار .\n\nالتحضير : 10 اسابيع مافيه تحضير - وآخر الاسابيع رصه الشيرمان وبدا يحضر .\n\nطريقة الشرح :\nيجيك الكلاس وينسرد على الكرسي كأنه في غرفة نومه ويفرفر في السلايدات -كلاسه عبارة عن مضيعة للوقت وما تستفيد منه شيء - انسان ما ادري كيف الجامعة جايبتهم والله سبك .\n\nالكويزات :\nعلى اساس بوب كويز وفي نهاية الترم ماشفنا شي بس خلاها بونص حضور\nالمياجر:\nالميجر الاول كان على اساس انه كوردنيتد لكن على ارض الواقع كان كل دكتور لحاله\nولما عرف الشيرمان اجبرهم يخلونه كومن (الافرج 59)\nالميجر الثاني كان كومن الافرج 45\nالفاينل كل دكتور لحاله الافرج 65\nهههههههههههههههه\nكورس عبارة عن فوضة ماتعرف لا اللي لك ولا اللي عليك - ندخل الميجر ولا ندري كم عليه من 100\n\nالثورة :\nبعد الفوضة اللي صارت في الميجر الثاني حيث ان شن بو يفضل المسائل (ياليته يشرح عاد مسائل مثل العالم ) والسبيعي وعثمان يحبون الكونسبت ----بين هذا وهذا الطلاب كلوها صح -الدكاترة ساحبين على ام الكتاب وكل واحد يشرح من مصادره وفي النهاية يبون الاختبار كومن شلوووووووووووووووون\n\nكانت الشرارة هي الميجر الثاني - وشن بو ارسل ايميل وقال انا وظيفتي الرئيسية هنا اني اعمل ابحاث فهمت مافهمت مايعنيني - لما قلنا للشيرمان عصب وبدأت الثورة\nقدمنا شكوى للعميد وتجاوب معنا وجمع طلاب السكاشن كلهم وسمع منا وسمعنا منه - وقرر فصل الكورس وكل مدرس يضع اختبار طلابه وكذلك القريدات .\nالمهم من نتائج الثورة ان شن بو بدا يكتب على السبورة ومايستخدم السلايدات - لكن اخلاقه وتعامله اصبح اسوء من اول فأنت تتعامل مع طفل والله حرفيا طفل - ماتدري ودك تكفخه على وجهه ولا تسايسه -------- المهم المدرس هذا سيء لدرجة انه انسان مريض نفسي - تحصله على كل وقت في مكتبه ولما تقفل معه يرسل ايميل طول بعرض يهدد وما ادري ايش يقول - طبعا هالانسان مهارات الخطابة وجه لوجه ماعنده فهو يخاف ويرتبك مايعرف يتحاور فهو لما يرسل بالايميل يحط حرته .\n\nالفاينل\nقال في الكلاس مش كومبرهنسف\nرسل بعدها ايميل انه كومبرهنسف\n\nالقريد النهائي: والله العظيم انه عطانا قريدات جيدة مقارنة بالسبيعي وعثمان لكنه سيء والله سيء\nاعطيه F ,وادفه F+\n\nالصوت: الاكسنت سيء لا هو يفهم ولا احنا نفهم\nإضافات :\nتخيلوا جاي الميجر الثانية بالبجامة هههههههههههه والله انسان غريب متناقض …\nالمضحك احد الطلاب حصل حسابه في الفيس بوك وطلع الولد يتهكم على المملكة وانها مافيها ترفيه ومدري ايش … باسط في مكتبه 24/7 ويبي يشوف ترفيه !!!!!!!!!!!1", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485830-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chen-bo/177579/3", "user": "user9840", "ts": 1515512184000, "tid": 177579, "pn": 3}}]}', 1515512184000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sultan_salman_1419-econ101', 'stk-sultan_salman_1419', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f177579", "n": "Dr. Chen Bo", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Econ 101 - Term 171\n\nالتحضير : في البداية ما كان يحضر … في نصف الترم أصبح يحضر حتى أخر 5 دقائق من الكلاس … آخر الترم أول 5 دقائق فقط … والتحضير بتستفيد منه آخر الترم في البونص وغيره … نصيحة لا تخلي أحد يحضر لك لأنك بتأخذ F في التحضير وهذه بتأثر في موضوع البونص\n\nطريقة الشرح : تقريبا أول ثلاثة أرباع من الترم كان يستخدم السلايدات … طريقة سيئة مع شرح غير جيد للمحتوى … لدرجة انك في بعض الحصص تطلع وانت ما استفدت أي شي … في الربع الاخير أصبح يستخدم السبورة وتحسن شرحه بشكل لا بأس به\n\nالكويزات : عبارة عن بونص … صعبة وما تفهم منها أي شيء … المحتوى اللي أخذته شيء ( لو افترضنا انك فهمت المحتوى أصلا ) واللي بتشوفه في الكويز شي ثاني\n\nالمياجر : صعبة … لا تضيع الميجر الأول لأنه رغم صعوبته الإ أنه أسهل ميجر … الميجر الثاني صعب جدا ولو جبت فيه 70% وفوق أنت أسطورة … أفرج الميجر الأول 59% …أفرج الميجر الثاني 49% … للجزء الرياضي النصيب الأكبر في المياجر ( جزء متوسط الصعوبة في الميجر الاول وصعب جدا في الميجر الثاني )\n\nالفاينل : صعب جدا … تحتاج تذاكر من السلايدات والكتاب والهوومورك ( والهومورك لحاله قصة ) … 60 سؤال مقسمة على 40 درجة … للجزء النظري النصيب الأكبر ( وهذا الجزء لا يضيع منك لانه يعتبر الجزء الأسهل ) والجزء الرياضي ( صعب ومشكلته أن كل سؤال يعتمد على اللي قبله … بحيث اذا ما عرفت السؤال الأول ما راح تحل الثاني ) … الأفرج كان تحت 50%\n\nالقريد النهائي : D بدون الدف … C مع الدف\n\nالصوت : ضعيف شوي … تحتاج إلى الجلوس في الأمام لكي تسمع جيدا … بالنسبة للأكسنت ما راح تفهمه في البداية لكن مع الوقت راح يصير سهل بالنسبة لك\n\nإضافات :\n\n1- بالنسبة للهومورك لا تتعب نفسك وتحاول حله لأنه صعب جدا وأساسًا محتوى الهومورك مختلف على اللي درسناه … الحلول موجودة في النت اكتب السؤال وبيجيك الحل ( تقريبا 90% من حلول الهومورك موجودة في النت … تبي تحل بنفسك الأمر راجع لك لكن لازم تعرف أنه بيصححها وبيحسبها عليك بعدين … هذا على افتراض انك تقدر تحلها … لذلك لا تتعب نفسك والجأ للنت أفضل لك\n\n2- قبل بداية أي ميجر أو فاينل … يحاول يرسل ايميلات طويلة عن أشياء كثيرة وبعض الأحيان يزبد ( خذ المفيد منها واسحب على الباقي )\n\n3- الرجال دف بشكل غير طبيعي في موضوع القريدات … A+ من 80 والباقي عليك الحساب … أقل طالب جاب 33 ومع ذلك نجح بD … فيه 3 طلاب رسبوا بسبب سوء السلوك\n\n4- بعد الميجر الثاني رحنا للتشيرمان وشرحنا له الوضع في المادة … من بعد ما تكلم التشيرمان مع الدكتور والدكتور تغير 360 درجة للأسوأ طبعا ما عدا الشرح تحسن بشكل طفيف\n\n5- بعد ما يرسل القريدات نصيحة لا تطلب منه قريد أفضل الإ لو أنت تستحقه ( على سبيل المثال خطأ في أحد الاسئلة أو خطأ في تصحيح الاختبار ) … غير كذا لو تطلب منه قريد أفضل بدون سبب بيروح يشيك الهومورك والتحضير وأشياء ثانية وبدل ما يزيد قريدك ممكن ينقص\n\n6- درجات الميجر الثاني كانت سيئة لدرجة ان الاستاذ عدلها مرتين … لعل هذا يشرح لك تأثير الشرح السيء على درجات الطلاب\n\n7- في الميجر الثاني بعض الاسئلة كانت كومون … وهذه مصيبة لأن كل مدرس يعتمد على وسيلة مختلفة في الشرح\n\nفي النهاية الدكتور شرحه غير جيد للأمانة … لكن مقارنة بالسبيعي وعثمان يعتبر أسطورة بسبب توزيع القريدات عنده … إذا أخذت المادة معه اعرف انك بتعتمد على نفسك بشكل كبير جدا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485994-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chen-bo/177579/5", "user": "sultan_salman_1419", "ts": 1515770323000, "tid": 177579, "pn": 5}}]}', 1515770323000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-makkahboy-econ101', 'stk-makkahboy', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f177579", "n": "Dr. Chen Bo", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ECON101- 171\nالتحضير : لمدة نصف ترم وأكثر مافي تحضير بعدين جاه كلام من التشيرمان وصار يحضر بورقة وكان البعض يحضر خويه وقفط االقريد النهائي: D (هذي عشان دفته شوي في الدرجات)\nطريقة الشرح: يمسك السلايد والسلايد يكون مختصر ويشرح فيه بنبرة صوت تجيب الملل جدا!!! (واحدة من الكلاسات نص الشباب كانوا عالجوالات وربي من الطفش)\nالكويزات : كانت بوب كويزز. والظاهر حسبها ك بونص وكانت جيدة في القريد النهائي (وللأمانة ما حضرت إلا كويز واحد وماحليته لأنه ماكان يعطينا خبر أصلا)\nالمياجر: عموم المادة ضياع زي ماذكروا الإخوان مابين كورديناتد والعكس. المهم والله كانت حالة ضياع لكن المياجر عموما صعبة سواء كانت كومون ولا كل مدرس يحطها لحاله\nالفاينل: أنا ما اعرف الفاينل كان كومون ولا كل واحد لحاله، الزبدة كان صععععب!!! وما أدري كيف خرجت منه والحمدلله\n\nإضافاتي :\n- من الأشياء اللي ساعدتني في الميجر الأول نوعا ما أنه حاولت أحل الهوموركين اللي كانت قبل الميجر بنفسي (مع أنها هوموركات طويييييييييلة!!!!!! جدا!) وكنت أعمل الحسابات بنفسي وأجيبها صح ولله الحمد وهذا ساعدني في المسائل الحسابية في الميجر الأول (طبعا هو حط الميجر فمن باب أولى أنه يكون فيه شبه بالهومورك والوضع تغير في الميجر الثاني)\n- درجات الهوموركات ما سلمنا إياها وسحب علينا بس كان ينزل السلوشن وحتى يسحب السلوشن من الموقع بعد فترة.\n-دكتور يحب التهديد والوعيد في عن طريق الإيميل ، وقدامك في المعاملة مايقدر يتكلم !! (استغفر الله بس)\nأن حسنته أنه كان بالبداية مايحضر وهذا ريحنا كثيييير! خصوصا من لغته الركيكة واللي صعب تسمعه إذا ماكنت قدام وتحتاج تجمع الكلام لأنه والله شخصيا ما كنت افهم عليه!!! عدم التحضير ريحنا وخلا كل واحد يذاكر بنفسه! قبل الميجر الأول ذاكرت بنفسي من الكتاب وماكنت احضر له كلاسات!!!! وجبت درجة أزين من الميجر الثاني اللي حضرت فيه الكلاسات :zipper_mouth_face:\nالشي الثاني : أنه فعلا دفنا دف أطيب من غيرنا\n\nزبدة الموضوع من وجهة نظري :هو أحسن السيء ، ولو نزلت معه حتعتمد على نفسك بشكل كبيييييير :muscle:\n\nالقريد النهائي : D (هذي عشانه دفنا في الفاينل قريد شوي ولا الأصل F)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1486438-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chen-bo/177579/6", "user": "makkahboy", "ts": 1516497783000, "tid": 177579, "pn": 6}}]}', 1516497783000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-econ101', 'stk-guest', 'ECON 101', 'doc', '{"docs": [{"id": "stk-dr-f177579", "n": "Dr. Chen Bo", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ECON 101 - T201 (online)\nالتحضير :\nسكرين شوت للحضور + التحضير بالكام\n\nطريقة الشرح :\nسلايدات من خارج المنهج، وبعدها جاب سلايدات المنهج، انهى الماتيريال في ٨ أسابيع وبعدها كنسل الكلاسات لباقي السمستر، شرح سيء جداً للامانة ولهجة غير واضحة وشرح لا يتعلق بالمنهج\n\nالكويزات : ايضا الكوزات معظمها فيها اسئلة لها علاقة بالمنهج ولكن مستواها للفلات المتقدمة (صعبة نوعاً ما) وفقط مسائل وحل بدون كونسبت (بعضها مسائل تحدي)\n\nالمياجر: كومن، اختيارات معظمها كونسبت وقليل مسائل\n\nالفاينلات : كومن، اختيارات معظمها كونسبت وقليل مسائل\n\nالقريد النهائي: F (بالنسبة للدكتور)\n\nالصوت: واضح ولكن لهجة صعبة شوي\n\nإضافات : من اسوء الدكاترة الي ممكن تاخذ معاه مادة لا انصح به ولا تنزل عنده الا لو مظطر مرة، الافضل انك تأجل المادة ولا تاخذ معه، سيء لدرجة لا تتصورونها شرحاً واخلاقاً وتعاملاً وينقص درجات ولا يرضى يقلك ليه، معقد جدا في اجرائات الاختبارات وتسليم الواجبات وغير متعاون، استغرب جدا كيف يمكن لشخص مثله ان يكون دكتور والاغرب ان يكون في جامعة البترول", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527490-econ101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chen-bo/177579/7", "user": "Guest", "ts": 1609594334000, "tid": 177579, "pn": 7}}]}', 1609594334000, 1794765163, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
